import '../../athlete/athlete_state_aggregator.dart';
import '../decision_engine/coach_decision_engine.dart';

/// Concrete actionable task generated by [CoachActionPlanner].
class PlannedCoachAction {
  final String id;
  final String
  type; // 'modify_workout', 'suggest_meal', 'create_reminder', 'generate_insight', 'start_challenge'
  final String title;
  final String description;
  final bool requiresConfirmation;
  final String? confirmationPrompt;
  final Map<String, dynamic> payload;
  final String priority; // 'high', 'medium', 'low'
  final String
  category; // 'workout', 'nutrition', 'recovery', 'habit', 'milestone'
  final String reasoning;
  final bool isExecuted;
  final DateTime createdAt;

  const PlannedCoachAction({
    required this.id,
    required this.type,
    required this.title,
    required this.description,
    this.requiresConfirmation = false,
    this.confirmationPrompt,
    this.payload = const {},
    this.priority = 'medium',
    this.category = 'workout',
    required this.reasoning,
    this.isExecuted = false,
    required this.createdAt,
  });

  PlannedCoachAction copyWith({
    String? id,
    String? type,
    String? title,
    String? description,
    bool? requiresConfirmation,
    String? confirmationPrompt,
    Map<String, dynamic>? payload,
    String? priority,
    String? category,
    String? reasoning,
    bool? isExecuted,
    DateTime? createdAt,
  }) {
    return PlannedCoachAction(
      id: id ?? this.id,
      type: type ?? this.type,
      title: title ?? this.title,
      description: description ?? this.description,
      requiresConfirmation: requiresConfirmation ?? this.requiresConfirmation,
      confirmationPrompt: confirmationPrompt ?? this.confirmationPrompt,
      payload: payload ?? this.payload,
      priority: priority ?? this.priority,
      category: category ?? this.category,
      reasoning: reasoning ?? this.reasoning,
      isExecuted: isExecuted ?? this.isExecuted,
      createdAt: createdAt ?? this.createdAt,
    );
  }

  Map<String, dynamic> toJson() => {
    'id': id,
    'type': type,
    'title': title,
    'description': description,
    'requires_confirmation': requiresConfirmation,
    if (confirmationPrompt != null) 'confirmation_prompt': confirmationPrompt,
    'payload': payload,
    'priority': priority,
    'category': category,
    'reasoning': reasoning,
    'is_executed': isExecuted,
    'created_at': createdAt.toIso8601String(),
  };
}

/// Central Action Planner transforming high-level [CoachDecision]s into
/// concrete, permission-gated, and executable [PlannedCoachAction]s.
class CoachActionPlanner {
  static CoachActionPlanner? _instance;
  static CoachActionPlanner get instance => _instance ??= CoachActionPlanner();

  /// Plans a prioritized sequence of coach actions from athlete state and coach decision.
  List<PlannedCoachAction> planActions({
    required AthleteStateSnapshot state,
    required CoachDecision decision,
  }) {
    final actions = <PlannedCoachAction>[];
    final now = DateTime.now();

    // -------------------------------------------------------------------------
    // 1. ACTION: MODIFY WORKOUT (Gated with confirmation for major changes)
    // -------------------------------------------------------------------------
    for (final adj in decision.trainingAdjustments) {
      final isMajorChange =
          adj.recommendRest ||
          adj.volumeMultiplier <= 0.8 ||
          adj.volumeMultiplier >= 1.05;

      final actionId =
          'act_mod_wo_${now.millisecondsSinceEpoch}_${actions.length}';
      final actionTitle = adj.recommendRest
          ? 'Switch Today to Active Recovery Mobility'
          : (adj.volumeMultiplier < 1.0
                ? 'Reduce Workout Volume by ${((1.0 - adj.volumeMultiplier) * 100).round()}%'
                : (adj.volumeMultiplier > 1.0
                      ? 'Apply Progressive Overload (+2.5kg)'
                      : 'Execute Standard Workout Routine'));

      actions.add(
        PlannedCoachAction(
          id: actionId,
          type: 'modify_workout',
          title: actionTitle,
          description: adj.description,
          requiresConfirmation: isMajorChange,
          confirmationPrompt: isMajorChange
              ? 'Atlas Coach suggests adjusting today\'s training: "${adj.description}". Would you like me to update your workout plan?'
              : null,
          payload: {
            'type': adj.type,
            'volume_multiplier': adj.volumeMultiplier,
            'recommend_rest': adj.recommendRest,
            'replacements': adj.exerciseReplacements,
          },
          priority: adj.recommendRest ? 'high' : 'medium',
          category: 'workout',
          reasoning: decision.reasoning,
          createdAt: now,
        ),
      );
    }

    // -------------------------------------------------------------------------
    // 2. ACTION: SUGGEST MEAL
    // -------------------------------------------------------------------------
    final targetProt = state.nutrition.targetProteinGrams;
    // Null when some food has no protein value: no claim of a shortfall.
    final protDelta = state.nutrition.proteinDelta;
    final isProtLow = protDelta != null && protDelta > 20.0;

    final mealTitle = isProtLow
        ? 'High-Protein Refuel Suggestion (35g+ Protein)'
        : 'Post-Workout Fuel & Micronutrient Balance';
    final mealDesc = isProtLow
        ? 'Add grilled chicken breast, Greek yogurt, or whey isolate to hit your ${targetProt.round()}g daily target.'
        : 'Maintain macro distribution with balanced complex carbs and lean protein.';

    actions.add(
      PlannedCoachAction(
        id: 'act_meal_${now.millisecondsSinceEpoch}',
        type: 'suggest_meal',
        title: mealTitle,
        description: mealDesc,
        requiresConfirmation: false,
        payload: {
          'target_protein_g': targetProt,
          'protein_delta_g': ?protDelta,
          if (protDelta == null) 'protein_total_incomplete': true,
          'meal_type': 'post_workout',
        },
        priority: isProtLow ? 'high' : 'medium',
        category: 'nutrition',
        reasoning:
            'Muscle protein synthesis requires optimal daily protein distribution.',
        createdAt: now,
      ),
    );

    // -------------------------------------------------------------------------
    // 3. ACTION: CREATE REMINDER
    // -------------------------------------------------------------------------
    final rec = decision.recoveryRecommendations.isNotEmpty
        ? decision.recoveryRecommendations.first
        : const RecoveryRecommendation(
            protocol: 'Hydration & Sleep',
            rationale: 'Daily maintenance',
          );

    actions.add(
      PlannedCoachAction(
        id: 'act_rem_${now.millisecondsSinceEpoch}',
        type: 'create_reminder',
        title: 'Recovery Routine Reminder',
        description: rec.protocol,
        requiresConfirmation: false,
        payload: {
          'target_sleep_hours': rec.sleepTargetHours,
          'protocol': rec.protocol,
        },
        priority: 'low',
        category: 'recovery',
        reasoning: rec.rationale,
        createdAt: now,
      ),
    );

    // -------------------------------------------------------------------------
    // 4. ACTION: GENERATE INSIGHT
    // -------------------------------------------------------------------------
    final consistency = state.behavior.consistencyScore.round();
    final streak = state.behavior.streakDays;

    actions.add(
      PlannedCoachAction(
        id: 'act_ins_${now.millisecondsSinceEpoch}',
        type: 'generate_insight',
        title: 'Consistency & Habit Progress Insight',
        description:
            'You are maintaining an average $consistency% consistency rating with a $streak-day active streak.',
        requiresConfirmation: false,
        payload: {'consistency_score': consistency, 'streak_days': streak},
        priority: 'low',
        category: 'milestone',
        reasoning:
            'Long-term hypertrophy and strength progression depend on habit continuity.',
        createdAt: now,
      ),
    );

    // -------------------------------------------------------------------------
    // 5. ACTION: START CHALLENGE (Gated with confirmation)
    // -------------------------------------------------------------------------
    if (state.behavior.streakDays >= 3 ||
        (state.recovery.isMeasured && state.recovery.readinessScore >= 80)) {
      actions.add(
        PlannedCoachAction(
          id: 'act_chal_${now.millisecondsSinceEpoch}',
          type: 'start_challenge',
          title: 'Join 7-Day Consistency Mastery Challenge',
          description:
              'Complete all scheduled training and hit protein targets for 7 consecutive days to earn +500 XP.',
          requiresConfirmation: true,
          confirmationPrompt:
              'Would you like to enroll in the "7-Day Consistency Mastery Challenge"?',
          payload: {
            'challenge_id': 'chal_consistency_7d',
            'duration_days': 7,
            'xp_reward': 500,
          },
          priority: 'medium',
          category: 'habit',
          reasoning:
              'Gamified consistency challenges increase 30-day athlete retention and adherence.',
          createdAt: now,
        ),
      );
    }

    return actions;
  }

  /// Executes a confirmed action or returns unconfirmed error if confirmation is required.
  Future<Map<String, dynamic>> executeAction(
    PlannedCoachAction action, {
    bool confirmed = false,
  }) async {
    if (action.requiresConfirmation && !confirmed) {
      return {
        'status': 'confirmation_required',
        'action_id': action.id,
        'prompt': action.confirmationPrompt ?? 'Please confirm this action.',
      };
    }

    // Execute the action payload
    return {
      'status': 'success',
      'action_id': action.id,
      'type': action.type,
      'executed_at': DateTime.now().toIso8601String(),
      'message': 'Action "${action.title}" executed successfully.',
    };
  }
}
